#include "hal_data.h"

#include "./globals/sil_globals.h"
/*******************************************************************************************************************//**
 * main() is generated by the RA Configuration editor and is used to generate threads if an RTOS is used.  This function
 * is called by main() when no RTOS is used.
 **********************************************************************************************************************/
/* LED Pins for EK-RA6M5 status indicators */
#define LED_BLUE  BSP_IO_PORT_00_PIN_06
#define LED_GREEN BSP_IO_PORT_00_PIN_07
#define LED_RED   BSP_IO_PORT_00_PIN_08

/* USB and UART status interfaces for blinking */
extern bool SIL_USB_PCDC_IsConnected(void);
extern sci_uart_instance_ctrl_t g_uart9_ctrl;

/* Blinking polling function called in the main loop */
void update_status_leds(void)
{
    static uint32_t blink_ticks = 0;
    blink_ticks++;
    
    if (blink_ticks >= 150000) // Control blinking frequency to ~1Hz
    {
        blink_ticks = 0;
        
        /* 1. USB Connection: Blink Blue LED if USB is up/connected; otherwise keep Off */
        if (SIL_USB_PCDC_IsConnected())
        {
            static bsp_io_level_t blue_level = BSP_IO_LEVEL_LOW;
            blue_level = (blue_level == BSP_IO_LEVEL_LOW) ? BSP_IO_LEVEL_HIGH : BSP_IO_LEVEL_LOW;
            R_IOPORT_PinWrite(&g_ioport_ctrl, LED_BLUE, blue_level);
        }
        else
        {
            R_IOPORT_PinWrite(&g_ioport_ctrl, LED_BLUE, BSP_IO_LEVEL_LOW);
        }
        
        /* 2. UART9 Status: Blink Green LED if UART9 is successfully opened; otherwise keep Off */
        if (g_uart9_ctrl.open)
        {
            static bsp_io_level_t green_level = BSP_IO_LEVEL_LOW;
            green_level = (green_level == BSP_IO_LEVEL_LOW) ? BSP_IO_LEVEL_HIGH : BSP_IO_LEVEL_LOW;
            R_IOPORT_PinWrite(&g_ioport_ctrl, LED_GREEN, green_level);
        }
        else
        {
            R_IOPORT_PinWrite(&g_ioport_ctrl, LED_GREEN, BSP_IO_LEVEL_LOW);
        }
    }
}

/* 🚨 [System Crash Diagnostics Indicator] 🚨
   Override the weak HardFault_Handler to blink the RED LED furiously if system crashes! */
void HardFault_Handler(void)
{
    /* Force Turn off Blue and Green status LEDs immediately */
    R_IOPORT_PinWrite(&g_ioport_ctrl, LED_BLUE,  BSP_IO_LEVEL_LOW);
    R_IOPORT_PinWrite(&g_ioport_ctrl, LED_GREEN, BSP_IO_LEVEL_LOW);
    
    /* Rapid blink of the RED LED for clear crash visual feedback */
    while (1)
    {
        R_IOPORT_PinWrite(&g_ioport_ctrl, LED_RED, BSP_IO_LEVEL_HIGH);
        for (volatile int i = 0; i < 800000; i++);
        R_IOPORT_PinWrite(&g_ioport_ctrl, LED_RED, BSP_IO_LEVEL_LOW);
        for (volatile int i = 0; i < 800000; i++);
    }
}

void hal_entry(void)
{
    /* APP1 Startup Defense: Immediately turn off all LEDs from previous boot stages */
    R_IOPORT_PinWrite(&g_ioport_ctrl, LED_BLUE,  BSP_IO_LEVEL_LOW);
    R_IOPORT_PinWrite(&g_ioport_ctrl, LED_GREEN, BSP_IO_LEVEL_LOW);
    R_IOPORT_PinWrite(&g_ioport_ctrl, LED_RED,   BSP_IO_LEVEL_LOW);

    SIL_GLOBALS_Enter1();
    SIL_GLOBALS_Enter2();

    while ((SIL_GLOBALS_GetStatus() >= GLOBALS_STS_MAINLOOP1) &&
           (SIL_GLOBALS_GetStatus() <= GLOBALS_STS_MAINLOOP2)) {

        /* Asynchronously poll and blink Status LEDs */
        update_status_leds();

        switch (SIL_GLOBALS_GetStatus()) {
        case GLOBALS_STS_MAINLOOP1:
            SIL_GLOBALS_MainLoop1();
            break;
        case GLOBALS_STS_MAINLOOP2:
            SIL_GLOBALS_MainLoop2();
            break;
        default:
            break;
        }
    }

    SIL_GLOBALS_Exit();


#if BSP_TZ_SECURE_BUILD
    /* Enter non-secure code */
    R_BSP_NonSecureEnter();
#endif
}

